import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, color, positionLocal, uniform, mul, add, fract, sin, dot, vec2, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight, Color } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10', surface: '#14141a', ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38'
  };

  const root = new Group();
  root.name = 'editorial-oversized-type';

  // --- Lights (node-local rim + fill) ---
  const ambient = new AmbientLight(new Color(colors.paper), 0.35);
  root.add(ambient);
  const rim = new DirectionalLight(new Color(colors.accent), 0.9);
  rim.position.set(-3, 2, 4);
  root.add(rim);

  // --- Backdrop editorial plate with vertical engineered gradient + grain ---
  const plateGeo = new PlaneGeometry(7, 5.5, 1, 1);
  const plateMat = new MeshBasicNodeMaterial();

  const cTop = color(colors.background);   // #0b0b10 at top
  const cBot = color(colors.surface);      // #14141a at bottom

  const vUv = uv();
  // vertical gradient: top -> bottom
  const grad = mix(cBot, cTop, vUv.y);

  // 1.5% monochrome grain (static hash)
  const hash = fract(mul(sin(dot(vUv, vec2(12.9898, 78.233))), 43758.5453));
  const grain = mul(add(hash, float(-0.5)), float(0.015));
  plateMat.colorNode = add(grad, vec3(grain, grain, grain));

  const plate = new Mesh(plateGeo, plateMat);
  plate.position.set(0, 0, -0.05);
  root.add(plate);

  // --- Text blocks ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const getByRole = (role) => items.filter((i) => i.role === role);
  const kicker = getByRole('kicker')[0]?.text ?? 'NOVA ATELIER / JOURNAL';
  const heroItems = getByRole('hero');
  const heroLine1 = heroItems[0]?.text ?? 'PRECISION IS';
  const heroLine2 = heroItems[1]?.text ?? 'A HABIT.';
  const body = getByRole('body')[0]?.text ??
    'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.';
  const caption = getByRole('caption')[0]?.text ?? 'ISSUE 12 / JULY 2026';

  const X = -3.1;
  const blocks = [];

  // Kicker
  const kickerMesh = ctx.fontAtlas.createText(kicker, {
    fontSize: 18, color: colors.accent, align: 'left', letterSpacingPx: 3
  });
  kickerMesh.position.set(X, 1.7, 0.02);
  root.add(kickerMesh);
  blocks.push(kickerMesh);

  // Hero line 1 - letterpress shadow behind
  const heroShadow1 = ctx.fontAtlas.createText(heroLine1, {
    fontSize: 124, color: colors.ink, align: 'left'
  });
  heroShadow1.position.set(X - 0.015, 0.9 - 0.015, 0.0);
  root.add(heroShadow1);

  const hero1 = ctx.fontAtlas.createText(heroLine1, {
    fontSize: 124, color: colors.paper, align: 'left'
  });
  hero1.position.set(X, 0.9, 0.03);
  root.add(hero1);
  blocks.push(hero1);
  hero1.userData._shadow = heroShadow1;

  // Hero line 2 - letterpress shadow behind
  const heroShadow2 = ctx.fontAtlas.createText(heroLine2, {
    fontSize: 124, color: colors.ink, align: 'left'
  });
  heroShadow2.position.set(X - 0.015, 0.25 - 0.015, 0.0);
  root.add(heroShadow2);

  const hero2 = ctx.fontAtlas.createText(heroLine2, {
    fontSize: 124, color: colors.paper, align: 'left'
  });
  hero2.position.set(X, 0.25, 0.03);
  root.add(hero2);
  blocks.push(hero2);
  hero2.userData._shadow = heroShadow2;

  // Accent underline rule (emissive)
  const ruleGeo = new PlaneGeometry(2.2, 0.05, 1, 1);
  const ruleMat = new MeshStandardNodeMaterial();
  ruleMat.colorNode = color(colors.accent);
  ruleMat.emissiveNode = mul(color(colors.accent), float(1.2));
  ruleMat.roughness = 0.6;
  ruleMat.metalness = 0.0;
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(X + 1.1, -0.15, 0.02);
  root.add(rule);

  // Body paragraph
  const bodyMesh = ctx.fontAtlas.createText(body, {
    fontSize: 26, color: colors.paper, align: 'left', maxWidthPx: 620
  });
  bodyMesh.position.set(X, -0.8, 0.02);
  root.add(bodyMesh);
  blocks.push(bodyMesh);

  // Caption
  const captionMesh = ctx.fontAtlas.createText(caption, {
    fontSize: 18, color: colors.paper, align: 'left', letterSpacingPx: 2
  });
  captionMesh.position.set(X, -1.9, 0.02);
  root.add(captionMesh);
  blocks.push(captionMesh);

  // --- Entrance animation: rise-in top-to-bottom with 80ms stagger ---
  const tl = gsap.timeline();

  blocks.forEach((b, i) => {
    b.position.y += 0.4;
    tl.to(b.position, {
      y: b.position.y - 0.4,
      duration: 0.7,
      ease: 'power3.out'
    }, i * 0.08);
    if (b.userData._shadow) {
      const s = b.userData._shadow;
      s.position.y += 0.4;
      tl.to(s.position, {
        y: s.position.y - 0.4,
        duration: 0.7,
        ease: 'power3.out'
      }, i * 0.08);
    }
  });

  // Rule draws scaleX 0->1 after hero lands
  rule.scale.x = 0;
  const rulePivotX = X;
  rule.position.x = rulePivotX;
  const drawRule = () => {
    rule.scale.x = 0;
    rule.position.x = rulePivotX;
  };
  drawRule();
  // Anchor rule left by animating scale + position
  tl.to(rule.scale, {
    x: 1,
    duration: 0.5,
    ease: 'power2.out',
    onUpdate: () => {
      rule.position.x = rulePivotX + 1.1 * rule.scale.x;
    }
  }, 0.5);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    plateGeo.dispose();
    plateMat.dispose();
    ruleGeo.dispose();
    ruleMat.dispose();
    root.traverse((o) => {
      if (o.isMesh && o !== plate && o !== rule) {
        o.geometry?.dispose?.();
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.());
        else o.material?.dispose?.();
      }
    });
  };

  return root;
}
